import Sub from "./subReLearn"
import "./ReLearn.css"

export default function () {
  return (
    <>
    <Root/>
    </>
  );
}

import { useState, } from "react"
export function Screen() {
  const [arr, wow] = useState([1,2,3,4,5])
  function Riversa() {
    wow([...arr].reverse())
  }
  return (
    <>
    <button onClick={Riversa}>click</button>
    {arr}
    </>
  );
}



